try {
  const contentItems = $json.content;
  if (!Array.isArray(contentItems)) {
    throw new Error('Response has no content array');
  }
  const textItem = contentItems.find(c => c.type === 'text');
  if (!textItem || !textItem.text) {
    throw new Error('No text content item found in response');
  }
  let raw = textItem.text.trim();
  raw = raw.replace(/^```json\s*/i, '').replace(/\s*```\s*$/, '').trim();
  raw = raw.replace(/^```\s*/, '').replace(/\s*```\s*$/, '').trim();
  const parsed = JSON.parse(raw);
  if (!parsed.status) parsed.status = 'analyzed';
  if (typeof parsed.quality_score !== 'number') parsed.quality_score = 1;
  if (!parsed.entity_type) parsed.entity_type = 'irrelevant';
  parsed.created_at = new Date().toISOString();
  return [{ json: { ...parsed } }];
} catch (err) {
  return [{
    json: {
      created_at: new Date().toISOString(),
      status: 'skipped',
      quality_score: 1,
      entity_type: 'irrelevant',
      source_type: 'manual_test',
      platform: '',
      source_url: '',
      parsed_at: '',
      published_at: '',
      freshness_status: 'unknown',
      company_name: '',
      profile_name: '',
      profile_url: '',
      region: '',
      service_type: 'unknown',
      offer_text: '',
      terms: '',
      contact_public: '',
      text_context: '',
      detected_need: '',
      competitor_strength: 1,
      lead_signal_score: 1,
      content_idea_score: 1,
      reason: 'Failed to parse Claude response: ' + err.message,
      recommended_action: 'ignore',
      raw_response_preview: JSON.stringify($json.content || '').substring(0, 500)
    }
  }];
}
